def f(A,pri):
    h=len(A); w=len(A[0]); cnt=Counter(x for row in A for x in row); bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in A]
    def val(v):
        return 7 if pri==1 and v==1 else (4 if pri==2 and v==2 else None)
    for r in range(h):
        for c in range(w):
            if A[r][c]!=bg: continue
            nbs={A[x][y] for x in range(max(0,r-1),min(h,r+2)) for y in range(max(0,c-1),min(w,c+2))}
            o=(1 in nbs), (2 in nbs)
            if pri==1:
                if o[0]: out[r][c]=7
                elif o[1]: out[r][c]=4
                else: pass
            else:
                if o[1]: out[r][c]=4
                elif o[0]: out[r][c]=7
                else: pass
    return out
